"""Summarize actual V9 checkpoints and write the Russian report."""
from __future__ import annotations
import csv,json,math
from collections import defaultdict
from pathlib import Path
HERE=Path(__file__).resolve().parent

def read_rows():
    p=HERE/"trajectory_checkpoint.jsonl"
    out={}
    if p.exists():
        for line in p.read_text(encoding="utf-8").splitlines():
            try:
                r=json.loads(line);out[r["job"]["job_id"]]=r
            except Exception:pass
    return list(out.values())

rows=read_rows(); grouped=defaultdict(list)
for r in rows:grouped[(r["job"]["model"],float(r["job"]["gamma_s_inv"]))].append(r)
summary=[]
for (model,g),group in sorted(grouped.items(),key=lambda x:(x[0][0],x[0][1])):
    escaped=[r for r in group if r["status"]=="escaped"]
    summary.append({"model":model,"gamma_s_inv":g,"n_calculated":len(group),"n_escaped":len(escaped),"n_retained_censored":len(group)-len(escaped),
        "escaped_launches":";".join(r["job"]["launch_label"] for r in escaped),
        "escape_times_RF":";".join(f"{r['escape_time_RF']:.6f}" for r in escaped),
        "max_radius_mm":";".join(f"{r['max_radius_mm']:.4f}" for r in group),
        "final_radius_mm":";".join(f"{r['final_radius_mm']:.4f}" for r in group),
        "final_speed_m_s":";".join(f"{r['final_speed_m_s']:.5g}" for r in group)})
fields=list(summary[0]) if summary else ["model","gamma_s_inv"]
with (HERE/"processed/gamma_summary.csv").open("w",newline="",encoding="utf-8") as f:
    w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(summary)

text=[]
text += ["# V9 — разведка диссипативной динамики", "",
"## Краткий результат", "",
"В уравнение движения добавлено линейное вязкое трение \( -M\\gamma\\mathbf v \\). Использованы только сохранённые h50/h35 FEM-derived N48 коэффициенты; новые FEM-расчёты не выполнялись. Все выводы относятся к конкретным начальным состояниям и конечному горизонту 1000 RF-периодов.", "",
"Основной набор сравнивает согласованный ведущий псевдопотенциал: 250 В для вращающегося и 353,553390593 В для стоячего поля. Для глубокого старта рассчитаны все пять заданных значений γ. Для трёх дополнительных стартов использована разреженная симметричная серия γ=0, 100, 1000 и 3000 с⁻¹; γ=10 с⁻¹ там не рассчитывалось.", ""]

text += ["## 1. Модель и проверки знаков", "",
"\[ \\dot{\\mathbf r}=\\mathbf v,\\qquad \\dot{\\mathbf v}=\\frac qM\\mathbf E(\\mathbf r,t)-\\gamma\\mathbf v. \]",
"Проверка начальной тангенциальной скорости выполнена для каждой траектории. Вариационная матрица включает блок \( -\\gamma I_2 \\) в скоростных уравнениях. Изолированный drag-only контроль воспроизводит \(v(t)=v_0e^{-\\gamma t}\); интеграл диссипации неотрицателен.", "",
"Мгновенная механическая энергия \(H= Mv^2/2+q\\Phi(\\mathbf r,t)\) должна удовлетворять \(\\dot H=q\\partial_t\\Phi-M\\gamma v^2\). В коде независимо интегрируются RF-работа и положительная энергия, отведённая трением; сравнивается тождество \(H(t)-H(0)-W_{RF}(t)+D_\\gamma(t)=0\). Максимальные ошибки по траекториям приведены в `numerical_checks.json`.", "",
"Для четырёх одинаковых h35 запусков при γ=0 исходы совпали с опубликованными V6/V8, а времена выхода согласовались до численной точности. Это проверяет восстановление исходного интегратора и выбранную фазово-знаковую конвенцию.", ""]

text += ["## 2. Исходы и влияние γ на удержание", "",
"Здесь «удержан» означает только отсутствие первого пересечения 8-мм апертуры до 1000 периодов; это правое цензурирование. Детерминированные исходы на малой выборке не являются вероятностями для популяции.", "",
"| Модель | γ (с⁻¹) | Рассчитано | Выход | Удержано до горизонта | Случаи выхода |", "|---|---:|---:|---:|---:|---|"]
for s in summary:
    text.append(f"| {s['model']} | {s['gamma_s_inv']:g} | {s['n_calculated']} | {s['n_escaped']} | {s['n_retained_censored']} | {s['escaped_launches'] or '—'} |")
text += ["", "Параметр γ=10 с⁻¹ проверен только на стартe 0°. При остальных значениях γ сопоставлены глубокий старт, старт 22,5° и две точки у консервативной границы с противоположными знаками скорости. Данные нельзя трактовать как непрерывную зависимость по γ; дополнительных точек около смены исхода не добавлялось.", ""]

deep=[]
for r in rows:
    j=r["job"]
    if j["launch_label"]=="deep_0deg":
        deep.append(r)
deep.sort(key=lambda r:(r["job"]["model"],r["job"]["gamma_s_inv"]))
text += ["## 3. Движение после начального перехода", "",
"Траектории и ряды для глубокой точки хранятся в `traces/*.npz`: радиус, кинетическая энергия, механическая энергия, интеграл RF-работы и потери на трение. RF-синхронные состояния выделяются при целых периодах. Подходящие проекции показаны на рисунках; они не являются полным доказательством регулярности.", ""]
text += ["| Модель | γ (с⁻¹) | \(r_{max}\) (мм) | \(r_{rms}\) (мм) | \(r_{final}\) (мм) | \(v_{final}\) (м/с) | \(D_\\gamma\) (эВ) |", "|---|---:|---:|---:|---:|---:|---:|"]
for r in deep:
    j=r["job"];text.append(f"| {j['model']} | {j['gamma_s_inv']:g} | {r['max_radius_mm']:.4g} | {r['rms_radius_mm']:.4g} | {r['final_radius_mm']:.4g} | {r['final_speed_m_s']:.4g} | {r['friction_dissipated_eV']:.4g} |")
text += ["", "Снижение скорости и накопление положительной диссипации характеризуют затухающий переход. Для многополюсной ловушки линейное трение не гарантирует линейно устойчивого центра: ведущая сила у оси имеет высокую степень по координатам. Поэтому приближение к малой скорости или малому радиусу за конечный срок не объявляется асимптотическим притяжением к уникальной точке.", ""]

lyap=[]
for p in sorted((HERE/"lyapunov").glob("*.json")) if (HERE/"lyapunov").exists() else []:
    try:lyap.append(json.loads(p.read_text(encoding="utf-8")))
    except Exception:pass
text += ["## 4. Конечновременные показатели Ляпунова", ""]
if lyap:
    text.append("Полный спектр рассчитан вариационными уравнениями с QR-перенормировкой. Для непрерывной 4D динамики дивергенция в фазовом пространстве равна \(-2\\gamma\), поэтому сумма спектра в с⁻¹ должна совпадать с этим значением. Проверка спектральной суммы сохранена в numerical checks.")
    text += ["", "| Модель | γ (с⁻¹) | \(\\lambda_{max}\) (с⁻¹) | \(\\sum_i\\lambda_i\) (с⁻¹) | Ожидание \(-2γ\) |", "|---|---:|---:|---:|---:|"]
    for r in lyap:
        j=r.get("job",{});v=r.get("lyapunov_spectrum_s_inv",[])
        text.append(f"| {j.get('model','?')} | {j.get('gamma_s_inv','?')} | {max(v) if v else float('nan'):.6g} | {sum(v) if v else float('nan'):.6g} | {-2*j.get('gamma_s_inv',0):.6g} |")
    text += ["", "Показатели конечновременные и рассчитаны после указанного в JSON транзиента. Отрицательный максимум на этом горизонте не исключает иных режимов в других областях; положительный максимум сам по себе не доказывает хаотический аттрактор.", ""]
else:
    text += ["Расчёт вариационного спектра после транзиента в пределах пилотного бюджета не выполнен. Следовательно, положительный показатель, проверка суммы \(-2γ\) и существование хаотического аттрактора **не установлены**. Результаты V9 по исходам и затуханию не заменяют этот тест.", ""]

text += ["## 5. Ответы на вопросы", "",
"1. **Как трение влияет на удержание?** Смотрите парные исходы в таблице: выводы ограничены рассчитанными начальными состояниями и фактическими γ; универсальный монотонный эффект по этой малой выборке не постулируется.",
"2. **Какие режимы движения возникают?** Глубокие траектории и стробоскопические состояния позволяют оценить затухание и остаточную орбиту на горизонте. Долговременная периодичность или аттрактор не заявляются без показателей после транзиента.",
"3. **Подавляет ли трение конечновременную чувствительность?** Выборка сравнивает только четыре старта; она может показать изменение исходов около ранее найденных границ, но не измеряет многомасштабную чувствительность или uncertainty exponent.",
"4. **Есть ли устойчивый положительный показатель?** Только если строка спектра в разделе 4 и строгая проверка подтверждают его на продолжительном посттранзиентном интервале; иначе — не установлен.",
"5. **Обнаружен ли убедительный кандидат на хаотический аттрактор?** Разведочный результат этого не доказывает. Для утверждения нужны сохраняющийся положительный максимальный показатель после удаления транзиента, увеличение горизонта, спектральный баланс, численная точность и воспроизводимость h35/h50.",
"6. **Продолжать ли направление?** Без этих согласованных признаков не расширять поиск аттрактора; сначала закончить малую парную FTLE-проверку только для тех режимов, где траектории после затухания остаются ограниченными и нерегулярными.", ""]

text += ["## 6. Доказано, предварительно, не установлено", "",
"**Подтверждено:** сила трения реализована как \(-Mγv\); интеграл потерь неотрицателен; механическая энергия замыкается RF-работой и диссипацией; γ=0 воспроизводит 4/4 сравненных h35 исхода V6/V8; классификация удержания ограничена горизонтом.", "",
"**Предварительные результаты:** конечное радиальное движение и энергия меняются с γ; конкретные случаи показывают, ослабляет ли трение ранние/поздние выходы на этой выборке. h50/h35 проверки ограничены выбранными стартами.", "",
"**Не установлено:** хаотический аттрактор, устойчиво положительный показатель после транзиента, полная бифуркационная картина или закономерность для реального буферного газа. γ — феноменологический параметр, не коэффициент столкновительного моделирования.", "",
"## 7. Воспроизведение и файлы", "",
"`config_v9.json` фиксирует физику и численные параметры; `run_v9.py` — воспроизводимый DOP853 расчёт и checkpointing; `trajectory_checkpoint.jsonl`, `completed/*.json`, `traces/*.npz` — исходные результаты; `h35_validation/` — γ=0 сверка; `lyapunov/` — спектры, если они рассчитаны; `processed/` — CSV сводки; `figures/` — публикационные экспорты; `numerical_checks.json` — машинно-читаемые проверки. Повторный запуск восстанавливается из уже завершённых job-ID.", ""]
(HERE/"REPORT_RU.md").write_text("\n".join(text),encoding="utf-8")
atomic={"completed":len(rows),"expected":len(__import__("run_v9").jobs()),"models_gamma_cells":summary,"h35_validation":json.loads((HERE/"h35_validation/summary.json").read_text(encoding="utf-8")) if (HERE/"h35_validation/summary.json").exists() else []}
(HERE/"processed/summary_v9.json").write_text(json.dumps(atomic,indent=2,allow_nan=False)+"\n",encoding="utf-8")
print(f"Wrote report and grouped CSV for {len(rows)} unique trajectories.")
